import json
with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def get_packages(d):
    result = {}
    for proj in d.get('projects', []):
        pname = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                key = (pname, pkg['id'], fw['framework'])
                result[key] = pkg['resolvedVersion']
    return result

b = get_packages(baseline)
a = get_packages(after)
changes = []
unchanged = 0
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(key)
    av = a.get(key)
    if bv != av:
        changes.append((key, bv, av))
    else:
        unchanged += 1

print(f'Unchanged: {unchanged}, Changed: {len(changes)}')
for c in changes:
    print(f'  {c[0][0]} | {c[0][1]} ({c[0][2]}): {c[1]} -> {c[2]}')
"

